WITH RankedPosts AS (SELECT P.Id AS PostId, P.Title, P.CreationDate, P.OwnerUserId, P.Score, RANK() OVER (PARTITION BY P.OwnerUserId ORDER BY P.Score DESC NULLS FIRST) AS PostRank, (SELECT COUNT(*) FROM Comments AS C WHERE C.PostId = P.Id) AS CommentCount, (SELECT COUNT(*) FROM Votes AS V WHERE V.PostId = P.Id AND V.VoteTypeId = 2) AS UpvoteCount, (SELECT COUNT(*) FROM Votes AS V WHERE V.PostId = P.Id AND V.VoteTypeId = 3) AS DownvoteCount FROM Posts AS P WHERE P.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), UserBadges AS (SELECT U.Id AS UserId, COUNT(B.Id) AS BadgeCount FROM Users AS U LEFT JOIN Badges AS B ON U.Id = B.UserId GROUP BY U.Id), PostHistorySummary AS (SELECT PH.PostId, GROUP_CONCAT(PHT.Name, ', ') AS HistoryTypes, COUNT(PH.Id) AS EditCount FROM PostHistory AS PH JOIN PostHistoryTypes AS PHT ON PH.PostHistoryTypeId = PHT.Id GROUP BY PH.PostId) SELECT U.DisplayName, R.PostId, R.Title, R.CreationDate, R.Score, R.CommentCount, R.UpvoteCount, R.DownvoteCount, COALESCE(B.BadgeCount, 0) AS BadgeCount, COALESCE(PH.HistoryTypes, 'No History') AS HistoryTypes, COALESCE(PH.EditCount, 0) AS EditCount FROM RankedPosts AS R JOIN Users AS U ON R.OwnerUserId = U.Id LEFT JOIN UserBadges AS B ON U.Id = B.UserId LEFT JOIN PostHistorySummary AS PH ON R.PostId = PH.PostId WHERE R.PostRank = 1 ORDER BY R.Score DESC NULLS FIRST LIMIT 100